def _poll_events(self, on_done):
    """Runs only while an operation is active: drains the event queue and
    hands the result to on_done, then stops (the idle state needs no loop)."""
    try:
        while True:
            kind, payload = self.events.get_nowait()
            if kind == "done":
                self.busy = False
                self._set_busy(False)
                self._refresh_buttons()
                if payload:
                    self.status_var.set(payload)
                    messagebox.showerror("Valt", payload)
                on_done()
                return
    except queue.Empty:
        pass
    self.after(80, lambda: self._poll_events(on_done))

